export interface Serializer<T> {
  serialize(input: T): string
}

export class SerializerRegistry {
  private map = new Map<string, Serializer<any>>()

  register(name: string, serializer: Serializer<any>): void {
    this.map.set(name, serializer)
  }

  get(name: string): Serializer<any> {
    const serializer = this.map.get(name)
    if (!serializer) {
      throw new Error(`Serializer '${name}' not found`)
    }
    return serializer
  }
}

